def _pip_of(sym):
    return 0.01 if sym.endswith("JPY") else 0.0001


def _atr14(h, l, c, idx):
    """ATR14 in PRICE units over bars idx-13..idx
    (true range vs the previous close), the filed
    gen_univ86 definition. None when unavailable or
    not positive."""
    if idx < 14:
        return None
    hh = h[idx - 13:idx + 1]
    ll = l[idx - 13:idx + 1]
    pc = c[idx - 14:idx]
    tr = np.maximum(hh - ll,
                    np.maximum(np.abs(hh - pc),
                               np.abs(ll - pc)))
    v = float(tr.mean())
    return v if v > 0 else None


def _atrh_pips(h1_bars, sym, T):
    """H1 ATR14 in PIPS at the H1 bar ending at T
    (the last H1 bar starting at or before T-3600),
    the filed append_field87 definition. None when
    the H1 history at the slot is short or flat."""
    hb = (h1_bars or {}).get(sym)
    if hb is None:
        return None
    tsh, _o, hh, ll, ch = hb
    ih = int(np.searchsorted(tsh, T - 3600,
                             side="right")) - 1
    if ih < 14:
        return None
    hh_h = hh[ih - 13:ih + 1]
    ll_h = ll[ih - 13:ih + 1]
    pc_h = ch[ih - 14:ih]
    trh = np.maximum(hh_h - ll_h,
                     np.maximum(np.abs(hh_h - pc_h),
                                np.abs(ll_h - pc_h)))
    v = float(trh.mean() / _pip_of(sym))
    return v if v > 0 else None


def _tercile(atrh):
    """Volatility tercile of an atrH value: midrank
    percentile against ATRH_REF (DISC pairs), 0 / 1 /
    2 below 1/3 / below 2/3 / above; -1 when atrH is
    undefined."""
    if atrh is None or not (atrh > 0):
        return -1
    lo = bisect.bisect_left(ATRH_REF, atrh)
    hi = bisect.bisect_right(ATRH_REF, atrh)
    p = (lo + 0.5 * (hi - lo)) / len(ATRH_REF)
    if p < 1.0 / 3.0:
        return 0
    if p < 2.0 / 3.0:
        return 1
    return 2


def _cell(si, hour, side, tercile, mult):
    """The fitted CELLS entry for a candidate row:
    (n1, n2, cond_n, cond_exp, cond_win); keys absent
    from the table are ineligible under both
    nominators with zero statistics."""
    v = CELLS.get(f"{si}|{hour}|{side}|{tercile}|"
                  f"{mult}")
    if v is None:
        return (0, 0, 0, 0.0, 0.0)
    return v


def _maxdd(seq):
    """Observed max drawdown of a net sequence
    (running peak including the 0 baseline, minus
    the cumsum) — the battery's own definition, as
    filed in grade98._maxdd_np."""
    if not len(seq):
        return 0.0
    cum = np.cumsum(np.asarray(seq, dtype=np.float64))
    peak = np.maximum.accumulate(
        np.concatenate(([0.0], cum)))[:-1]
    return float(np.max(peak - cum))


def _trade_outcome(bars, sym, entry_s, side,
                   dist_price, mult, atr_pips):
    """The filed replay for one candidate: walk the
    192 M15 bars after the entry bar; SL-first on a
    same-bar tie; neither hit -> cap exit at the
    close of the 192nd bar, exit epoch entry + 48h.
    Returns (exit_epoch, net25); both None while the
    trade is unresolved in the available bars and
    the 48h cap bar is not yet present."""
    ts, _o, h, l, c = bars
    idx = int(np.searchsorted(ts, entry_s - 900))
    if idx >= len(ts) or ts[idx] != entry_s - 900:
        return None, None
    ph = h[idx + 1:idx + 1 + MAXHOLD_BARS]
    pl = l[idx + 1:idx + 1 + MAXHOLD_BARS]
    fwd = ts[idx + 1:idx + 1 + MAXHOLD_BARS]
    entry = float(c[idx])
    pip = _pip_of(sym)
    if len(ph) >= MAXHOLD_BARS:
        # full path available: exact filed replay
        if side > 0:
            sl_hit = pl <= entry - dist_price
            tp_hit = ph >= entry + dist_price
        else:
            sl_hit = ph >= entry + dist_price
            tp_hit = pl <= entry - dist_price
        isl = int(np.argmax(sl_hit)) if sl_hit.any() \
            else 10 ** 9
        itp = int(np.argmax(tp_hit)) if tp_hit.any() \
            else 10 ** 9
        if isl == 10 ** 9 and itp == 10 ** 9:
            gross = side * (float(c[idx + MAXHOLD_BARS])
                            - entry) / pip
            return entry_s + MAX_HOLD * 3600, \
                gross - COST_PIPS
        if isl <= itp:
            return int(fwd[isl]) + 900, -mult * atr_pips \
                - COST_PIPS
        return int(fwd[itp]) + 900, mult * atr_pips \
            - COST_PIPS
    # partial path (live): resolve only on an actual hit
    if side > 0:
        sl_hit = pl <= entry - dist_price
        tp_hit = ph >= entry + dist_price
    else:
        sl_hit = ph >= entry + dist_price
        tp_hit = pl <= entry - dist_price
    isl = int(np.argmax(sl_hit)) if sl_hit.any() else 10 ** 9
    itp = int(np.argmax(tp_hit)) if tp_hit.any() else 10 ** 9
    if isl == 10 ** 9 and itp == 10 ** 9:
        return None, None
    if isl <= itp:
        return int(fwd[isl]) + 900, -mult * atr_pips \
            - COST_PIPS
    return int(fwd[itp]) + 900, mult * atr_pips - COST_PIPS


def _slot_rows(T, m15_bars, h1_bars, m5_bars=None):
    """Candidate rows for one slot, in canonical
    order (symbol index, side desc, step asc). Each
    row: sym, side, mult, tercile, elig_n1, elig_n2,
    cell_n, cell_exp, cell_win (the filed conditioned
    cell statistics the rank keys read), entry_px,
    atr (pips), exit, net (exit/net None while
    unresolved in the available bars), entry_s. A
    symbol contributes rows only when its M15 entry
    bar (the bar ending at T) and the 14-bar ATR
    window are available, and the filed window
    rule (see header) does not suppress it. Rows at steps other than
    {2.0, 3.0} are never generated: they cannot be
    eligible under R423-PJW (see header). m5_bars is
    accepted for panel-signature parity and unused —
    the design reads M15 + H1 only."""
    rows = []
    hour = int((T // 3600) % 24)
    _feb4 = int(_dt.datetime(
        _dt.datetime.utcfromtimestamp(T).year, 2, 4,
        tzinfo=_dt.timezone.utc).timestamp())
    for sym in SYMBOLS:
        bars = m15_bars.get(sym)
        if bars is None:
            continue
        ts, _o, h, l, c = bars
        idx = int(np.searchsorted(ts, T - 900))
        if idx >= len(ts) or ts[idx] != T - 900 \
                or idx < 14:
            continue
        if len(ts) and ts[-1] >= _feb4 and (
                idx + MAXHOLD_BARS >= len(ts)
                or ts[idx + MAXHOLD_BARS] >= _feb4):
            continue  # the filed universe's window
            # rule (see header): no rows when the
            # 192-bar path would end after Feb 4
            # 00:00 UTC; inert when the series does
            # not reach that Feb 4 (live panels)
        pip = _pip_of(sym)
        atr_price = _atr14(h, l, c, idx)
        if atr_price is None:
            continue
        atr = float(atr_price / pip)
        entry_px = float(c[idx])
        tercile = _tercile(_atrh_pips(h1_bars, sym, T))
        si = SYM_IDX[sym]
        for side in (1, -1):
            for m in MULTS:
                n1, n2, cn, cexp, cwin = _cell(
                    si, hour, side, tercile, m)
                dist = m * atr * pip
                xp, net = _trade_outcome(
                    bars, sym, T, side, dist, m, atr)
                ck = -1 if tercile < 0 else (
                    ((si * 24 + hour) * 2
                     + (1 if side < 0 else 0)) * 6
                    + _ALL6.index(m)) * 3 + tercile
                rows.append({
                    "sym": sym, "side": side,
                    "mult": float(m),
                    "tercile": int(tercile),
                    "cell_key": int(ck),
                    "elig_n1": bool(n1),
                    "elig_n2": bool(n2),
                    "cell_n": int(cn),
                    "cell_exp": float(cexp),
                    "cell_win": float(cwin),
                    "score": float(cwin),
                    "entry_px": entry_px, "atr": atr,
                    "exit": xp, "net": net,
                    "entry_s": int(T)})
    return rows


class FillState:
    """The R423-PJW fill in live form: the champion
    agreement fill ("second_mg") under the WDIV-NAME
    re-sort and the PROTECTION clause P. Slots are
    processed in chronological order. State: the
    blocking ledger (max exit per symbol), the era
    segment's kept-net sequence (the DISC gate's
    input), the segment's per-ISO-week net ledger
    (the WDIV overlap's input) and its per-calendar
    -year (picks, wins) ledger (the protection's
    input); the segment ledgers reset when the era
    changes, exactly as filed \u2014 the blocking
    ledger is NOT reset \u2014 and the picks.

    Both orderings of the two nominators' lists are
    run per slot on scratch copies of the state:
    "off" keeps the champion order (N1 by
    (-cell_win, -cell_exp, position); N2 by
    (-cell_exp, -cell_n, position)); "name" re-sorts
    both lists by (overlap, champion position),
    overlap = |LOSE_WEEKS[cell] \u2229 the running
    book's currently-losing ISO week numbers|.
    Inside an ordering: agree -> N2's row, disagree
    -> N1's row, a single namer -> its row; at
    agreement slots a second pick (first row of
    N1's list on a different unblocked symbol) is
    admitted ungated outside the DISC era, and in
    the DISC era only through the filed drawdown
    gate (own net >= +5.0 and the segment max
    drawdown not increased).

    PROTECTION: at a protected slot (the slot's
    calendar year has >= 1 committed pick in the
    segment and its running win rate is
    <= T_FRACTION) where the two orderings' pick
    lists differ, the NAME list is refused \u2014
    the OFF list is committed instead \u2014
    whenever the NAME list would leave the year's
    win rate lower than the OFF list would."""

    def __init__(self):
        self.max_exit = {}
        self.seq = []
        self.run_net = {}
        self.year_state = {}
        self.era = None
        self.picks = []
        self.ev = {}

    # -- persistence --------------------------------
    def _ev(self, era):
        return self.ev.setdefault(era, {
            "slots_total": 0, "filled": 0,
            "unfilled_no_rows": 0,
            "unfilled_no_eligible": 0,
            "unfilled_all_blocked": 0,
            "pick1_secondbest": 0, "second_picks": 0,
            "second_possible": 0, "second_admitted": 0,
            "second_rejected": 0,
            "orderings_differ": 0, "protected_slots": 0,
            "refusals": 0})

    def to_dict(self):
        return {
            "max_exit": {k: ("inf" if v == float("inf")
                             else v)
                         for k, v in
                         self.max_exit.items()},
            "seq": list(self.seq), "era": self.era,
            "run_net": {str(k): v for k, v
                        in self.run_net.items()},
            "year_state": {str(k): list(v) for k, v
                           in self.year_state.items()},
            "picks": self.picks}

    def from_dict(self, d):
        self.max_exit = {k: (float("inf") if v == "inf"
                             else int(v))
                         for k, v in d.get("max_exit",
                                           {}).items()}
        self.seq = list(d.get("seq", []))
        self.era = d.get("era")
        self.run_net = {int(k): float(v) for k, v
                        in d.get("run_net",
                                 {}).items()}
        self.year_state = {int(k): [int(v[0]),
                                    int(v[1])]
                           for k, v in d.get(
                               "year_state",
                               {}).items()}
        self.picks = d.get("picks", [])

    # -- core ---------------------------------------
    def _append_pick(self, row, ts, layer):
        pick = {"sym": row["sym"], "entry_s": int(ts),
                "side": int(row["side"]),
                "mult": float(row["mult"]),
                "tercile": int(row["tercile"]),
                "entry_px": float(row["entry_px"]),
                "atr": float(row["atr"]),
                "score": float(row["score"]),
                "layer": layer,
                "exit": row["exit"],
                "net": row["net"]}
        self.picks.append(pick)
        return pick

    def resolve_pending(self, m15_bars):
        """Recompute unresolved picks from the bars now
        available; on resolution the pick's true exit
        replaces the blocking placeholder."""
        for pick in self.picks:
            if pick["exit"] is not None:
                continue
            bars = m15_bars.get(pick["sym"])
            if bars is None:
                continue
            dist = pick["mult"] * pick["atr"] \
                * _pip_of(pick["sym"])
            xp, net = _trade_outcome(
                bars, pick["sym"], pick["entry_s"],
                pick["side"], dist, pick["mult"],
                pick["atr"])
            if xp is None:
                continue
            pick["exit"] = int(xp)
            pick["net"] = float(net)
            ex = [p["exit"] if p["exit"] is not None
                  else float("inf")
                  for p in self.picks
                  if p["sym"] == pick["sym"]]
            self.max_exit[pick["sym"]] = max(ex)

    def _slot_picks(self, ts, era, rows, cand_a,
                    cand_b, order):
        """One ordering's pick list for a slot,
        computed on a scratch copy of the fill state
        (cycle_r423pjw._slot, verbatim semantics).
        Returns (positions, max_exit, seq, run_net):
        the scratch state after the picks."""
        max_exit = dict(self.max_exit)
        seq = list(self.seq)
        run_net = dict(self.run_net)
        cand_a = list(cand_a)
        cand_b = list(cand_b)
        if order == "name":
            losing = {w for w, v in run_net.items()
                      if v < 0}

            def ov(p):
                lw = LOSE_WEEKS.get(
                    rows[p]["cell_key"])
                return len(set(lw) & losing) if lw \
                    else 0

            cand_a = [p for _o, _q, p in sorted(
                (ov(p), q, p) for q, p
                in enumerate(cand_a))]
            cand_b = [p for _o, _q, p in sorted(
                (ov(p), q, p) for q, p
                in enumerate(cand_b))]
        picks = []

        def commit(p):
            row = rows[p]
            ex = row["exit"]
            max_exit[row["sym"]] = max(
                max_exit.get(row["sym"], -1),
                int(ex) if ex is not None
                else float("inf"))
            picks.append(p)
            if row["net"] is not None:
                seq.append(float(row["net"]))
                w = _weeknum(ts)
                run_net[w] = run_net.get(w, 0.0) \
                    + float(row["net"])

        n1 = n2 = None
        for p in cand_a:
            if max_exit.get(rows[p]["sym"], -1) <= ts:
                n1 = p
                break
        for p in cand_b:
            if max_exit.get(rows[p]["sym"], -1) <= ts:
                n2 = p
                break
        if n1 is None and n2 is None:
            return picks, max_exit, seq, run_net
        agree = n1 is not None and n2 is not None \
            and rows[n1]["sym"] == rows[n2]["sym"]
        if n1 is None:
            pick = n2
        elif n2 is None:
            pick = n1
        elif agree:
            pick = n2
        else:
            pick = n1
        commit(pick)
        if not agree:
            return picks, max_exit, seq, run_net
        cand2 = None
        for p in cand_a:
            if rows[p]["sym"] != rows[pick]["sym"] \
                    and p != pick \
                    and max_exit.get(rows[p]["sym"],
                                     -1) <= ts:
                cand2 = p
                break
        if cand2 is None:
            return picks, max_exit, seq, run_net
        if era == "disc":
            x = rows[cand2]["net"]
            admit = (x is not None) and (
                x >= ADM_MARGIN_DD) and (
                _maxdd(seq + [float(x)])
                <= _maxdd(seq) + 1e-9)
            if not admit:
                return picks, max_exit, seq, run_net
        commit(cand2)
        return picks, max_exit, seq, run_net

    def process_slot(self, ts, era, rows):
        """rows: the slot's candidate rows in
        canonical order (see _slot_rows). Returns the
        pick records made at this slot (0, 1 or 2)."""
        if era != self.era:
            self.era = era
            self.seq = []
            self.run_net = {}
            self.year_state = {}
        e = self._ev(era)
        e["slots_total"] += 1
        if not rows:
            e["unfilled_no_rows"] += 1
            return []
        cand_a = sorted(
            (p for p in range(len(rows))
             if rows[p]["elig_n1"]),
            key=lambda p: (-rows[p]["cell_win"],
                           -rows[p]["cell_exp"], p))
        cand_b = sorted(
            (p for p in range(len(rows))
             if rows[p]["elig_n2"]),
            key=lambda p: (-rows[p]["cell_exp"],
                           -rows[p]["cell_n"], p))
        name = self._slot_picks(ts, era, rows, cand_a,
                                cand_b, "name")
        off = self._slot_picks(ts, era, rows, cand_a,
                               cand_b, "off")
        chosen = name
        if name[0] != off[0]:
            e["orderings_differ"] += 1
            year = _dt.datetime.utcfromtimestamp(
                ts).year
            p_y, w_y = self.year_state.get(
                year, (0, 0))
            if p_y >= 1 and (
                    w_y / p_y) <= T_FRACTION + 1e-12:
                e["protected_slots"] += 1

                def _wins(pos):
                    return sum(
                        1 for p in pos
                        if rows[p]["net"] is not None
                        and rows[p]["net"] > 0)

                r_name = (w_y + _wins(name[0])) / (
                    p_y + len(name[0]))
                r_off = (w_y + _wins(off[0])) / (
                    p_y + len(off[0]))
                if r_name < r_off - 1e-12:
                    chosen = off
                    e["refusals"] += 1
        positions, self.max_exit, self.seq, \
            self.run_net = chosen
        if not positions:
            if not cand_a and not cand_b:
                e["unfilled_no_eligible"] += 1
            else:
                e["unfilled_all_blocked"] += 1
            return []
        e["filled"] += 1
        made = []
        year = _dt.datetime.utcfromtimestamp(ts).year
        for j, p in enumerate(positions):
            made.append(self._append_pick(
                rows[p], ts,
                "first" if j == 0 else "second"))
            ys = self.year_state.setdefault(
                year, [0, 0])
            ys[0] += 1
            if rows[p]["net"] is not None and \
                    rows[p]["net"] > 0:
                ys[1] += 1
        if len(made) == 2:
            e["second_picks"] += 1
            e["second_admitted"] += 1
        return made


def _state_path():
    from core.new8_candidate import default_state_path
    return default_state_path(SYSTEM_NAME)


def _bars_from_frame(df):
    """App frame (DataFrame with a time column and OHLC)
    -> (ts, o, h, l, c) numpy arrays sorted by time."""
    if df is None or not len(df):
        return None
    try:
        tcol = next(c for c in df.columns
                    if c.lower() in ("datetime", "time",
                                     "timestamp"))
        ts = (pd.to_datetime(df[tcol], utc=True)
              .astype("int64") // 10 ** 9).to_numpy(np.int64)
        o = df["Open"].to_numpy(np.float64)
        h = df["High"].to_numpy(np.float64)
        l = df["Low"].to_numpy(np.float64)
        c = df["Close"].to_numpy(np.float64)
    except Exception:
        return None
    order = np.argsort(ts, kind="stable")
    return (ts[order], o[order], h[order], l[order],
            c[order])


class _Form:
    """The slot stream settled through the filed
    agreement fill. Persisted: the fill state
    (blocking ledger, segment sequence, picks), the
    delivered ledger and the processed checks."""

    def __init__(self, path=None):
        self.path = path or _state_path()
        self.fill = FillState()
        self.delivered = []
        self.processed = []
        self._load()

    def _load(self):
        import json
        if not self.path or not os.path.exists(self.path):
            return
        try:
            with open(self.path) as fh:
                d = json.load(fh)
        except Exception:
            return
        self.processed = d.get("processed", [])
        if "fill" in d:
            self.fill.from_dict(d["fill"])
        out = []
        for r in d.get("delivered", []):
            r = dict(r)
            for k in ("check", "entry_time", "exit_time",
                      "entry_candle"):
                if r.get(k) is not None:
                    r[k] = pd.Timestamp(r[k])
            out.append(r)
        self.delivered = out

    def save(self):
        import json
        if not self.path:
            return
        os.makedirs(os.path.dirname(
            os.path.abspath(self.path)), exist_ok=True)

        def ser(rows):
            out = []
            for r in rows:
                dd = dict(r)
                for k in ("check", "entry_time",
                          "exit_time", "entry_candle"):
                    if dd.get(k) is not None:
                        dd[k] = pd.Timestamp(
                            dd[k]).isoformat()
                out.append(dd)
            return out
        with open(self.path, "w") as fh:
            json.dump({"system": SYSTEM_NAME,
                       "fill": self.fill.to_dict(),
                       "delivered": ser(self.delivered),
                       "processed": self.processed}, fh)

    def step(self, frames, check_time_utc, m15_frames,
             open_symbols=(), m5_frames=None):
        chk = pd.Timestamp(check_time_utc)
        if str(chk) in self.processed:
            return [r for r in self.delivered
                    if pd.Timestamp(r["check"]) == chk]
        T = int(chk.timestamp())
        T -= T % 3600  # entries fire at H:00 UTC; the H:30
        # stamp is the evaluation label
        if m15_frames is None:
            m15_frames = fetch_cycle60g_m15_frames()
        m15_bars = {}
        for sym in SYMBOLS:
            b = _bars_from_frame(
                m15_frames.get(sym) if m15_frames else None)
            if b is not None:
                m15_bars[sym] = b
        h1_bars = {}
        for sym in SYMBOLS:
            b = _bars_from_frame(
                frames.get(sym) if frames else None)
            if b is not None:
                h1_bars[sym] = b
        m5_bars = {}
        if m5_frames:
            for sym in SYMBOLS:
                b = _bars_from_frame(m5_frames.get(sym))
                if b is not None:
                    m5_bars[sym] = b
        self.fill.resolve_pending(m15_bars)
        era = "disc" if _dt.datetime.utcfromtimestamp(
            T).year <= 2023 else "audit"
        rows = _slot_rows(T, m15_bars, h1_bars, m5_bars)
        picks = self.fill.process_slot(T, era, rows)
        entry_candle = pd.Timestamp(
            _dt.datetime.utcfromtimestamp(T))
        out = []
        for pk in picks:
            dd = {"check": chk, "symbol": pk["sym"],
                  "direction": "BUY" if pk["side"] > 0
                  else "SELL",
                  "entry_candle": entry_candle,
                  "entry_time": entry_candle,
                  "entry_px": float(pk["entry_px"]),
                  "tp_pips": float(pk["mult"]
                                   * pk["atr"]),
                  "sl_pips": float(pk["mult"]
                                   * pk["atr"]),
                  "exit_time": entry_candle
                  + pd.Timedelta(hours=MAX_HOLD),
                  "mult": float(pk["mult"]),
                  "layer": pk["layer"],
                  "system": SYSTEM_NAME}
            self.delivered.append(dd)
            out.append(dd)
        self.processed.append(str(chk))
        self.save()
        return out


_STATE = None


def _state():
    global _STATE
    if _STATE is None:
        _STATE = _Form()
    return _STATE


def load_state_form(path=None):
    if path is not None:
        return _Form(path=path)
    return _state()


def is_cycle60g_check_time(ts) -> bool:
    t = pd.Timestamp(ts)
    return t.hour in CYCLE60G_CHECK_HOURS \
        and t.minute == 30


def panel_entries(frames: dict, check_time_utc,
                  m15_frames: dict | None = None,
                  open_symbols=(),
                  m5_frames: dict | None = None
                  ) -> pd.DataFrame:
    form = _state()
    out = form.step(frames, check_time_utc, m15_frames,
                    open_symbols, m5_frames)
    if isinstance(out, pd.DataFrame):
        return out
    if not out:
        return pd.DataFrame()
    return pd.DataFrame(out)


def walk_ledger():
    """The delivered cycle60g stream."""
    return [dict(r) for r in _state().delivered]


def fetch_cycle60g_m15_frames(state=None):
    from core.cycle89_best import fetch_cycle89_m15_frames
    return fetch_cycle89_m15_frames()


def evaluate_cycle60g_signals(frames: dict,
                                 check_time_utc,
                                 m15_frames: dict | None
                                 = None):
    return panel_entries(frames, check_time_utc,
                         m15_frames)


def select_cycle60g_entries(signals: pd.DataFrame,
                               open_symbols=()
                               ) -> pd.DataFrame:
    if signals is None or not len(signals):
        return signals
    return signals
